wire  			DRP_CLK_IN;//50MHz
wire  			SYSCLK_IN; //100MHz
reg	[19:0]	cnt_0 = 0;
reg				trig_ad9516;
wire				lcok;  
	
ip_mmcme2_clk i_ip_mmcme2_clk
 (// Clock in ports
	.CLK_IN1		(clk_in		),
  // Clock out ports
	.CLK_OUT1	(DRP_CLK_IN	),
	.CLK_OUT2	(SYSCLK_IN	),
  // Status and control signals
	.RESET		(0				),
	.LOCKED		(lock			)
 );

always @(posedge DRP_CLK_IN or negedge lock)
begin
   if(!lock)
      cnt_0 <= 0;
   else if(cnt_0==20'hF_FFFF)
		cnt_0 <= cnt_0;
	else
		cnt_0 <= cnt_0 + 1'b1;
end

always @(posedge DRP_CLK_IN or negedge lock)
begin
   if(!lock)
      trig_ad9516 <= 1'b0;
	else if(cnt_0==16'h2_0000)
		trig_ad9516 <= 1'b1;
	else
		trig_ad9516 <= 1'b0;
end

always @(posedge drpclk_in_i)
begin
    drpclk_heartbeat_cnt <= drpclk_heartbeat_cnt + 1'b1;
end

m_ad9516_ctl i_m_ad9516_ctl(
//input clk
	.clk_50m_in							(DRP_CLK_IN					),
//reset ,active low
	.rst_n								(lock							),
//trig start singal
	.trig_in								(trig_ad9516				),
//chip select
	.cs_n_out							(ad9516_cs_n_out			),
//serial clk
	.sclk_out							(ad9516_sclk_out			),
//serial data out
	.sdata_out							(ad9516_sdata_out			),
	.ad9516_refsel_out				(ad9516_refsel_out		),
	.ad9516_pdwn_out					(ad9516_pdwn_out			),
	.ad9516_rstn_out					(ad9516_rstn_out			),
//serial data out
	.syn_n_out							(ad9516_syn_n_out			),
	.cfg_end_out						()
);



